'use strict';
(() => {
  const $ = id => document.getElementById(id);
  const allowed = new Set(['image/jpeg', 'image/png', 'image/webp']);
  const pad = (n, w = 2) => String(n).padStart(w, '0');

  let records = [];        // {id, file, url, watermark:{...}}
  let activeId = null;
  let working = false;

  const brandAsset = new Image();
  let brandReady = false;
  brandAsset.onload = () => { brandReady = true; prepareBrand(); if (activeId) updatePreview(); };
  brandAsset.src = 'data:image/png;base64,';

  // 预处理“水印相机”标志：提取白色文字 alpha，渲染时不再触碰像素
  let brandMask = null;
  function prepareBrand() {
    const sourceX = 22, sourceY = 42, sourceW = 218, sourceH = 67;
    const mask = document.createElement('canvas');
    mask.width = sourceW; mask.height = sourceH;
    const mctx = mask.getContext('2d');
    mctx.drawImage(brandAsset, sourceX, sourceY, sourceW, sourceH, 0, 0, sourceW, sourceH);
    try {
      const pixels = mctx.getImageData(0, 0, sourceW, sourceH);
      for (let i = 0; i < pixels.data.length; i += 4) {
        const light = (pixels.data[i] + pixels.data[i + 1] + pixels.data[i + 2]) / 3;
        const alpha = Math.max(0, Math.min(255, (light - 175) * 3.2));
        pixels.data[i] = 255; pixels.data[i + 1] = 255; pixels.data[i + 2] = 255; pixels.data[i + 3] = alpha;
      }
      mctx.putImageData(pixels, 0, 0);
      brandMask = mask;
    } catch (e) {
      brandMask = null; // 失败则不画标志，不影响主流程
    }
  }

  const wmKeys = ['watermarkEnabled', 'time', 'date', 'lng', 'lat', 'location', 'watermarkStyle', 'size', 'lineHeight', 'shade', 'brandMark'];
  const wmControl = k => $(k);

  function currentWatermarkState() {
    const state = {};
    wmKeys.forEach(k => {
      const el = wmControl(k);
      state[k] = el.type === 'checkbox' ? el.checked : el.value;
    });
    return state;
  }
  function applyWatermarkToControls(state) {
    wmKeys.forEach(k => {
      const el = wmControl(k);
      if (state[k] === undefined) return;
      if (el.type === 'checkbox') el.checked = Boolean(state[k]); else el.value = state[k];
    });
    syncOutputs();
  }

  function status(text, kind = 'info') {
    const el = $('status');
    el.textContent = text;
    el.className = `status show ${kind}`;
  }
  function syncOutputs() {
    $('sizeOut').textContent = `${$('size').value}%`;
    $('lineHeightOut').textContent = `${$('lineHeight').value}%`;
    $('shadeOut').textContent = `${$('shade').value}%`;
  }

  const overlayName = m => ({ watermark: '仅水印', label: '仅标签', both: '水印 + 标签', none: '原图（都不叠加）' })[m] || m;
  const channelSuffix = m => ({ watermark: '仅水印', label: '仅标签' })[m] || '';

  function fileName(r, mode) {
    const ext = $('format').value === 'image/png' ? 'png' : 'jpg';
    const rawBase = r.file.name.replace(/\.[^.]+$/, '') || '图片';
    let name = rawBase;
    const ch = channelSuffix(mode);
    if (ch) name += `_${ch}`;
    return `${name}.${ext}`;
  }

  function validations() {
    const errors = [];
    if (!records.length) errors.push('请先选择至少一张图片。');
    const names = new Set();
    // 导出重名检查按“水印+标签”（无通道后缀）为准
    records.forEach(r => {
      const name = fileName(r, 'both');
      if (names.has(name)) errors.push(`原文件名重复：${name}。请先在电脑中改名后再上传，避免 ZIP 内覆盖。`);
      names.add(name);
    });
    return [...new Set(errors)];
  }

  function drawChecks() {
    const errors = validations(), list = $('checks');
    list.innerHTML = '';
    if (errors.length) {
      errors.forEach(t => {
        const li = document.createElement('li');
        li.className = 'bad'; li.textContent = `✕ ${t}`; list.append(li);
      });
    } else {
      const li = document.createElement('li');
      li.className = 'ok'; li.textContent = `✓ ${records.length} 张图片，可直接导出。`; list.append(li);
    }
    const ready = !errors.length && !working;
    ['exportAll', 'exportAllWatermark', 'exportAllLabel'].forEach(id => { $(id).disabled = !ready; });
    ['exportOne', 'exportOneWatermark', 'exportOneLabel'].forEach(id => { $(id).disabled = !activeId || working; });
  }

  function loadImage(file) {
    return new Promise((resolve, reject) => {
      const url = URL.createObjectURL(file), img = new Image();
      img.onload = () => { URL.revokeObjectURL(url); resolve(img); };
      img.onerror = () => { URL.revokeObjectURL(url); reject(new Error('图片读取失败')); };
      img.src = url;
    });
  }

  // ---------- 绘制 ----------
  function roundRect(ctx, x, y, w, h, r) {
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.arcTo(x + w, y, x + w, y + h, r);
    ctx.arcTo(x + w, y + h, x, y + h, r);
    ctx.arcTo(x, y + h, x, y, r);
    ctx.arcTo(x, y, x + w, y, r);
    ctx.closePath();
  }
  function wrap(ctx, text, max, limit) {
    const result = [];
    for (const paragraph of String(text).trim().split(/\r?\n/)) {
      let line = '';
      for (const char of paragraph) {
        if (ctx.measureText(line + char).width > max && line) { result.push(line); line = char; }
        else line += char;
      }
      if (line) result.push(line);
    }
    if (!result.length) result.push('未填写地点');
    return result.slice(0, limit);
  }
  function formatDate(value) {
    if (!value) return '未填写日期';
    const d = new Date(`${value}T12:00:00`);
    if (Number.isNaN(d)) return value;
    const week = ['星期日', '星期一', '星期二', '星期三', '星期四', '星期五', '星期六'][d.getDay()];
    return `${d.getFullYear()}.${pad(d.getMonth() + 1)}.${pad(d.getDate())} ${week}`;
  }

  function drawWatermark(ctx, w, h, state) {
    if (state.watermarkEnabled === false) return;
    const scale = (h / 1706) * (Number(state.size) / 100), opacity = Number(state.shade) / 100;
    const start = Math.max(0, h - 570 * scale);
    const gradient = ctx.createLinearGradient(0, start, 0, h);
    gradient.addColorStop(0, 'rgba(6,12,19,0)');
    gradient.addColorStop(.32, `rgba(6,12,19,${opacity * .5})`);
    gradient.addColorStop(1, `rgba(6,12,19,${opacity})`);
    ctx.fillStyle = gradient;
    ctx.fillRect(0, start, w, h - start);
    if (state.watermarkStyle === 'audit') drawAuditWatermark(ctx, w, h, state, scale);
    else if (state.watermarkStyle === 'simple') drawSimpleWatermark(ctx, w, h, state, scale);
    else drawCardWatermark(ctx, w, h, state, scale);
    if (state.brandMark) drawBrandMark(ctx, w, h, scale);
  }
  function drawCardWatermark(ctx, w, h, state, scale) {
    const left = 28 * scale, baseY = h - 452 * scale, badgeH = 91 * scale, titleW = 128 * scale;
    const time = state.time || '--:--', timeFont = 48 * scale, lineH = 46 * scale * (Number(state.lineHeight || 120) / 100);
    ctx.save();
    ctx.font = `800 ${timeFont}px Arial,sans-serif`;
    const badgeW = titleW + ctx.measureText(time).width + 70 * scale;
    ctx.fillStyle = 'rgba(247,249,247,.92)';
    roundRect(ctx, left, baseY, badgeW, badgeH, 13 * scale); ctx.fill();
    roundRect(ctx, left + 4 * scale, baseY + 4 * scale, titleW - 5 * scale, badgeH - 8 * scale, 9 * scale);
    ctx.fillStyle = '#ffc72c'; ctx.fill();
    ctx.fillStyle = '#111'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.font = `800 ${44 * scale}px -apple-system,"PingFang SC",sans-serif`;
    ctx.fillText('打卡', left + titleW / 2, baseY + badgeH / 2);
    ctx.textAlign = 'left';
    ctx.font = `800 ${timeFont}px Arial,sans-serif`;
    ctx.strokeStyle = '#fff'; ctx.lineWidth = 4 * scale;
    ctx.strokeText(time, left + titleW + 16 * scale, baseY + badgeH / 2);
    ctx.fillStyle = '#1768ab';
    ctx.fillText(time, left + titleW + 16 * scale, baseY + badgeH / 2);
    const infoY = baseY + badgeH + 28 * scale, textX = left + 35 * scale;
    const maxW = Math.min(w - textX - 30 * scale, w * .76), font = 40 * scale;
    ctx.font = `500 ${font}px -apple-system,"PingFang SC",sans-serif`;
    const lines = wrap(ctx, state.location || '未填写地点', maxW, 4);
    ctx.fillStyle = '#ffc72c';
    ctx.fillRect(left, infoY - 5 * scale, 7 * scale, lines.length * lineH + 74 * scale);
    ctx.fillStyle = '#fff'; ctx.textBaseline = 'top';
    lines.forEach((line, i) => ctx.fillText(line, textX, infoY + i * lineH));
    ctx.font = `500 ${38 * scale}px -apple-system,"PingFang SC",sans-serif`;
    ctx.fillText(formatDate(state.date), textX, infoY + lines.length * lineH + 16 * scale);
    ctx.restore();
  }
  function drawAuditWatermark(ctx, w, h, state, scale) {
    const left = 28 * scale, maxW = w - left - 30 * scale, font = 35 * scale;
    const lineH = 48 * scale * (Number(state.lineHeight || 120) / 100);
    const time = `${state.date || '未填写日期'} ${state.time || '--:--'}`;
    const rows = [`经度：${state.lng || '--'}`, `纬度：${state.lat || '--'}`, `地址：${state.location || '未填写地点'}`, `时间：${time}`];
    ctx.save();
    ctx.font = `500 ${font}px -apple-system,"PingFang SC",sans-serif`;
    ctx.textBaseline = 'top';
    ctx.fillStyle = '#fff';
    ctx.strokeStyle = 'rgba(0,0,0,.7)';
    ctx.lineWidth = Math.max(2, 3 * scale);
    let expanded = [];
    rows.forEach(row => expanded.push(...wrap(ctx, row, maxW, 4)));
    const baseY = h - 28 * scale - expanded.length * lineH;
    expanded.forEach((line, i) => {
      const y = baseY + i * lineH;
      ctx.strokeText(line, left, y); ctx.fillText(line, left, y);
    });
    ctx.restore();
  }
  function drawSimpleWatermark(ctx, w, h, state, scale) {
    const left = 34 * scale, maxW = w - left - 34 * scale, font = 34 * scale;
    const lineH = 47 * scale * (Number(state.lineHeight || 120) / 100);
    const time = `${state.date ? state.date.replaceAll('-', '.') : '未填写日期'} ${state.time || '--:--'}`;
    const rows = [`时间  ${time}`, `经度  ${state.lng || '--'}`, `纬度  ${state.lat || '--'}`, `地点  ${state.location || '未填写地点'}`];
    ctx.save();
    ctx.font = `500 ${font}px -apple-system,"PingFang SC",sans-serif`;
    ctx.textBaseline = 'top';
    ctx.fillStyle = '#fff';
    ctx.shadowColor = 'rgba(0,0,0,.72)';
    ctx.shadowBlur = 4 * scale;
    ctx.shadowOffsetY = 2 * scale;
    let expanded = [];
    rows.forEach(row => expanded.push(...wrap(ctx, row, maxW, 4)));
    const baseY = h - 28 * scale - expanded.length * lineH;
    expanded.forEach((line, i) => ctx.fillText(line, left, baseY + i * lineH));
    ctx.restore();
  }
  function drawBrandMark(ctx, w, h, scale) {
    if (!brandMask) return;
    const sourceW = 218, sourceH = 67;
    const width = 210 * scale, height = sourceH / sourceW * width;
    const right = 28 * scale, bottom = 30 * scale;
    const x = w - right - width, y = h - bottom - height;
    ctx.save();
    ctx.shadowColor = 'rgba(0,0,0,.65)';
    ctx.shadowBlur = 3 * scale;
    ctx.shadowOffsetY = 2 * scale;
    ctx.drawImage(brandMask, x, y, width, height);
    ctx.restore();
  }
  function drawLabel(ctx, w, h, seq) {
    const size = Math.max(18, Math.round(Math.min(w, h) * Number($('labelScale').value)));
    const p = Math.round(size * .2), text = `${$('labelPrefix').value.trim()}${pad(seq)}`;
    ctx.save();
    ctx.font = `700 ${size}px Arial,"Microsoft YaHei",sans-serif`;
    ctx.textBaseline = 'top';
    ctx.lineWidth = Math.max(2, Math.round(size * .09));
    const white = $('labelColor').value === 'white';
    ctx.strokeStyle = white ? 'rgba(0,0,0,.45)' : 'rgba(255,255,255,.55)';
    ctx.fillStyle = white ? '#fff' : '#000';
    ctx.strokeText(text, p, p);
    ctx.fillText(text, p, p);
    ctx.restore();
  }

  async function renderCanvas(r, target, mode = 'both') {
    const img = await loadImage(r.file);
    const c = target || document.createElement('canvas');
    c.width = img.naturalWidth; c.height = img.naturalHeight;
    const ctx = c.getContext('2d');
    ctx.drawImage(img, 0, 0, c.width, c.height);
    const seq = records.indexOf(r) + 1;
    const wm = mode === 'watermark' || mode === 'both';
    const lb = mode === 'label' || mode === 'both';
    if (wm) drawWatermark(ctx, c.width, c.height, r.watermark);
    if (lb && $('labelEnabled').checked) drawLabel(ctx, c.width, c.height, seq);
    return c;
  }

  async function updatePreview() {
    const r = records.find(x => x.id === activeId), c = $('canvas');
    const mode = $('previewOverlay').value;
    $('overlaySummary').textContent = overlayName(mode);
    if (!r) {
      c.hidden = true;
      $('canvasWrap').querySelector('.empty').hidden = false;
      $('previewMeta').textContent = '请先选择图片';
      drawChecks();
      return;
    }
    try {
      $('previewMeta').textContent = `第 ${pad(records.indexOf(r) + 1)} 张 · 正在渲染`;
      await renderCanvas(r, c, mode);
      c.hidden = false;
      $('canvasWrap').querySelector('.empty').hidden = true;
      $('previewMeta').textContent = `第 ${pad(records.indexOf(r) + 1)} 张 / 共 ${records.length} 张 · ${r.file.name}`;
    } catch (e) {
      status(`预览失败：${e.message}`, 'error');
    }
    drawChecks();
  }

  // ---------- 列表 ----------
  function render() {
    const host = $('groups');
    host.innerHTML = '';
    $('count').textContent = records.length ? `已上传 ${records.length} 张图片` : '尚未上传图片';
    if (!records.length) {
      host.innerHTML = '<div class="no-files">先上传图片；顺序可以随时调整。</div>';
      drawChecks();
      return;
    }
    const rows = document.createElement('div');
    rows.className = 'rows';
    records.forEach((r, i) => {
      const row = document.createElement('article');
      row.className = `row${r.id === activeId ? ' active' : ''}`;

      const seq = document.createElement('div');
      seq.className = 'row-seq';
      seq.textContent = pad(i + 1);

      const img = document.createElement('img');
      img.className = 'thumb';
      img.src = r.url;
      img.alt = r.file.name;
      img.title = '点击预览';
      img.onclick = () => { activeId = r.id; applyWatermarkToControls(r.watermark); render(); updatePreview(); };

      const main = document.createElement('div');
      const nameEl = document.createElement('div');
      nameEl.className = 'row-name';
      nameEl.textContent = `原文件名：${r.file.name}（导出时保留原名）`;
      main.append(nameEl);

      const fs = document.createElement('div');
      fs.className = 'row-fields';
      fs.append(
        makeField('时间', 'time', r.watermark.time, v => { r.watermark.time = v; if (r.id === activeId) { applyWatermarkToControls(r.watermark); updatePreview(); } }),
        makeField('日期', 'date', r.watermark.date, v => { r.watermark.date = v; if (r.id === activeId) { applyWatermarkToControls(r.watermark); updatePreview(); } }),
        makeField('地点', 'text', r.watermark.location, v => { r.watermark.location = v; if (r.id === activeId) { applyWatermarkToControls(r.watermark); updatePreview(); } }),
      );
      main.append(fs);

      const actions = document.createElement('div');
      actions.className = 'row-actions';
      const edit = document.createElement('button');
      edit.textContent = '预览 / 精修';
      edit.onclick = () => { activeId = r.id; applyWatermarkToControls(r.watermark); render(); updatePreview(); };
      const up = document.createElement('button');
      up.textContent = '上移';
      up.disabled = i === 0;
      up.onclick = () => { [records[i - 1], records[i]] = [records[i], records[i - 1]]; render(); updatePreview(); };
      const down = document.createElement('button');
      down.textContent = '下移';
      down.disabled = i === records.length - 1;
      down.onclick = () => { [records[i + 1], records[i]] = [records[i], records[i + 1]]; render(); updatePreview(); };
      const del = document.createElement('button');
      del.textContent = '删除';
      del.onclick = () => {
        URL.revokeObjectURL(r.url);
        records = records.filter(x => x.id !== r.id);
        if (activeId === r.id) activeId = records[Math.min(i, records.length - 1)]?.id || null;
        render(); updatePreview();
        status('已删除，序号已重新排列。', 'info');
      };
      actions.append(edit, up, down, del);

      row.append(seq, img, main, actions);
      rows.append(row);
    });
    host.append(rows);
    drawChecks();
  }
  function makeField(label, kind, value, onChange) {
    const l = document.createElement('label');
    l.textContent = label;
    const e = document.createElement('input');
    e.type = kind;
    e.value = value ?? '';
    e.addEventListener('input', () => onChange(e.value));
    e.addEventListener('change', () => onChange(e.value));
    l.append(e);
    return l;
  }

  // ---------- 上传 ----------
  async function addFiles(fileList) {
    const input = [...fileList], good = [], bad = [];
    for (const f of input) {
      if (!allowed.has(f.type)) { bad.push(f.name); continue; }
      try {
        const probe = await loadImage(f);
        if (probe.naturalWidth) good.push(f);
      } catch { bad.push(f.name); }
    }
    if (good.length) {
      const base = currentWatermarkState();
      good.forEach(f => records.push({ id: crypto.randomUUID(), file: f, url: URL.createObjectURL(f), watermark: { ...base } }));
      if (!activeId) activeId = records[0]?.id || null;
      render(); updatePreview();
      status(`已添加 ${good.length} 张图片，序号按当前顺序从 01 开始。`, 'ok');
    }
    if (bad.length) status(`以下图片无法读取或格式不支持：${bad.join('、')}`, 'error');
    $('files').value = '';
  }

  // ---------- 导出 ----------
  function blob(canvas) {
    return new Promise((resolve, reject) =>
      canvas.toBlob(b => b ? resolve(b) : reject(new Error('图片编码失败')), $('format').value, $('format').value === 'image/jpeg' ? .95 : undefined));
  }
  function save(data, name) {
    const url = URL.createObjectURL(data), a = document.createElement('a');
    a.href = url; a.download = name;
    document.body.append(a); a.click(); a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 30000);
  }
  const baseLabels = {};
  async function withWork(button, work) {
    if (working) return;
    if (!baseLabels[button.id]) baseLabels[button.id] = button.textContent;
    working = true; drawChecks();
    try { await work(); }
    catch (e) { console.error(e); status(`生成失败：${e.message}`, 'error'); }
    finally { working = false; drawChecks(); button.textContent = baseLabels[button.id]; }
  }
  const exportSingle = (button, mode) => withWork(button, async () => {
    const r = records.find(x => x.id === activeId);
    if (!r) throw new Error('请先选择要导出的图片');
    button.textContent = '正在生成…';
    save(await blob(await renderCanvas(r, null, mode)), fileName(r, mode));
    status(`已开始下载：${fileName(r, mode)}`, 'ok');
  });
  const exportAll = (button, mode) => withWork(button, async () => {
    const errors = validations();
    if (errors.length) { render(); status('请先处理提示的问题再导出。', 'error'); return; }
    button.textContent = `正在生成 0/${records.length}…`;
    const zip = new JSZip();
    for (let i = 0; i < records.length; i++) {
      button.textContent = `正在生成 ${i + 1}/${records.length}…`;
      zip.file(fileName(records[i], mode), await blob(await renderCanvas(records[i], null, mode)));
    }
    const archive = await zip.generateAsync({ type: 'blob', compression: 'DEFLATE', compressionOptions: { level: 6 } });
    const ch = channelSuffix(mode);
    const zipName = `图片导出_${pad(1)}-${pad(records.length)}${ch ? '_' + ch : ''}.zip`;
    save(archive, zipName);
    status(`已生成 ${records.length} 张图片的 ZIP（${overlayName(mode)}）。原图未被修改。`, 'ok');
  });

  // ---------- 事件 ----------
  $('drop').onclick = () => $('files').click();
  $('files').onchange = e => addFiles(e.target.files);
  ['dragenter', 'dragover'].forEach(n => $('drop').addEventListener(n, e => { e.preventDefault(); $('drop').classList.add('over'); }));
  ['dragleave', 'drop'].forEach(n => $('drop').addEventListener(n, e => { e.preventDefault(); $('drop').classList.remove('over'); }));
  $('drop').addEventListener('drop', e => addFiles(e.dataTransfer.files));

  wmKeys.forEach(k => {
    const el = wmControl(k);
    const handler = () => {
      syncOutputs();
      const r = records.find(x => x.id === activeId);
      if (r) {
        r.watermark[k] = el.type === 'checkbox' ? el.checked : el.value;
        render(); updatePreview();
      }
      drawChecks();
    };
    el.addEventListener('input', handler);
    el.addEventListener('change', handler);
  });

  ['labelEnabled', 'labelColor', 'labelScale', 'labelPrefix', 'previewOverlay', 'format'].forEach(id => {
    $(id).addEventListener('input', () => { render(); updatePreview(); });
    $(id).addEventListener('change', () => { render(); updatePreview(); });
  });

  $('applyAll').onclick = () => {
    if (!records.length) return;
    const base = currentWatermarkState();
    records.forEach(r => r.watermark = { ...base });
    render(); updatePreview();
    status('当前水印设置已应用到全部图片。', 'ok');
  };

  $('exportOne').onclick = () => exportSingle($('exportOne'), 'both');
  $('exportOneWatermark').onclick = () => exportSingle($('exportOneWatermark'), 'watermark');
  $('exportOneLabel').onclick = () => exportSingle($('exportOneLabel'), 'label');
  $('exportAll').onclick = () => exportAll($('exportAll'), 'both');
  $('exportAllWatermark').onclick = () => exportAll($('exportAllWatermark'), 'watermark');
  $('exportAllLabel').onclick = () => exportAll($('exportAllLabel'), 'label');

  // 放大预览
  const modal = $('zoomModal'), zoomImg = $('zoomImg');
  function closeZoom() { modal.classList.remove('show'); zoomImg.src = ''; }
  $('canvas').addEventListener('click', () => {
    const c = $('canvas');
    if (c.hidden) return;
    zoomImg.src = c.toDataURL('image/jpeg', .92);
    modal.classList.add('show');
  });
  modal.addEventListener('click', closeZoom);
  document.addEventListener('keydown', e => { if (e.key === 'Escape') closeZoom(); });

  syncOutputs();
  drawChecks();
})();
